### Python

```python
import sys


def odd_manacher(arr):
    # 求整数数组 arr 的最长奇回文半径
    n = len(arr)
    d = [0] * n
    l, r = 0, -1
    ans = 0

    for i in range(n):
        # 初始化当前位置的半径
        if i > r:
            k = 1
        else:
            k = min(d[l + r - i], r - i + 1)

        # 向两边扩展
        while i - k >= 0 and i + k < n and arr[i - k] == arr[i + k]:
            k += 1

        d[i] = k
        ans = max(ans, k)

        # 更新当前最右回文区间
        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    return ans


def solve_one(n, c):
    stack = []

    # 用栈模拟原序列的全部消除
    for x in c:
        if stack and stack[-1] == x:
            stack.pop()
        else:
            stack.append(x)

    m = len(stack)

    # 原本已经可以消除的次数
    base = (n - m) // 2

    # 若已经全部消完，插入一个物品也不能产生新消除
    if m == 0:
        return base

    # 插入一次带来的最大额外消除次数
    extra = odd_manacher(stack)

    return base + extra


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    idx = 1
    ans = []

    for _ in range(t):
        n = data[idx]
        idx += 1
        c = data[idx:idx + n]
        idx += n
        ans.append(str(solve_one(n, c)))

    print("\n".join(ans))


if __name__ == "__main__":
    main()
```

