int oddManacher(const vector<int>& arr) {
    int n = arr.size();
    vector<int> d(n);
    int l = 0, r = -1;
    int ans = 0;

    for (int i = 0; i < n; i++) {
        int k;

        // 初始化当前位置的半径
        if (i > r) {
            k = 1;
        } else {
            k = min(d[l + r - i], r - i + 1);
        }

        // 向两边扩展
        while (i - k >= 0 && i + k < n && arr[i - k] == arr[i + k]) {
            k++;
        }

        d[i] = k;
        ans = max(ans, k);

        // 更新当前最右回文区间
        if (i + k - 1 > r) {
            l = i - k + 1;
            r = i + k - 1;
        }
    }

    return ans;
}

int solveOne(int n, const vector<int>& c) {
    vector<int> st;

    // 用栈模拟原序列的全部消除
    for (int x : c) {
        if (!st.empty() && st.back() == x) {
            st.pop_back();
        } else {
            st.push_back(x);
        }
    }

    int m = st.size();

    // 原本已经可以消除的次数
    int base = (n - m) / 2;

    // 若已经全部消完，插入一个物品也不能产生新消除
    if (m == 0) {
        return base;
    }

    // 插入一次带来的最大额外消除次数
    int extra = oddManacher(st);

    return base + extra;
}

